import React, { useState, useEffect } from "react";
import { Button, Form, Input, Row, Col, FormGroup, Collapse } from "reactstrap";
import { auth, db } from "../../firebase"; // Adjust the import according to your setup
import { doc, getDoc, setDoc, updateDoc } from "firebase/firestore"; // Firebase Firestore methods

const CarbonFootprintInput = () => {
  const [userData, setUserData] = useState({
    carUsageKm: "",
    vehicleType: "",
    fuelType: "",
    publicTransportTrips: "",
    publicTransportMode: "",
    flightsPerYear: "",
    electricityUsage: "",
    heatingMethod: "",
    homeSize: "",
    energyEfficientAppliances: false,
    dietType: "",
    meatFrequency: "",
    recyclingHabit: false,
    wasteGeneration: "",
    renewableEnergyUse: false,
    ecoFriendlyProducts: false,
    sustainableShopping: false,
    carbonOffsetProgram: "",
    carbonOffsetDetails: "",
    additionalNotes: "",
  });

  const [collapse, setCollapse] = useState({
    transportation: false,
    energy: false,
    food: false,
    waste: false,
    sustainable: false,
    offset: false,
    additionalNotes: false,
  });

  useEffect(() => {
    const fetchUserData = async () => {
      const user = auth.currentUser;
      if (user) {
        const userRef = doc(db, "users", `${user.uid}-footprint`);
        const docSnap = await getDoc(userRef);
        if (docSnap.exists()) {
          setUserData(docSnap.data());
        }
      }
    };
    fetchUserData();
  }, []);

  const handleChange = (e) => {
    const { id, value, type, checked } = e.target;
    setUserData({
      ...userData,
      [id]: type === "checkbox" ? checked : value,
    });
  };

  const toggleCollapse = (section) => {
    setCollapse((prevState) => ({
      ...prevState,
      [section]: !prevState[section],
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const user = auth.currentUser;
    if (user) {
      const userRef = doc(db, "users", `${user.uid}-footprint`);

      try {
        // Check if the document exists
        const docSnap = await getDoc(userRef);
        if (docSnap.exists()) {
          // Update the document if it exists
          await updateDoc(userRef, userData);
          alert("Carbon footprint updated successfully!");
        } else {
          // If the document doesn't exist, create a new one
          await setDoc(userRef, userData);
          alert("Carbon footprint created successfully!");
        }
      } catch (error) {
        console.error("Error updating footprint: ", error);
        alert("Failed to update footprint.");
      }
    }
  };

  return (
    <>
      <div className="container mt-5">
        <Form onSubmit={handleSubmit}>
          {/* Transportation Section */}
          <h6 className="heading-small text-muted mb-4">
            Transportation
            <Button
              color="link"
              onClick={() => toggleCollapse("transportation")}
              size="sm"
              className="float-right"
            >
              {collapse.transportation ? "Hide" : "Show"} Details
            </Button>
          </h6>
          <Collapse isOpen={collapse.transportation}>
            <Row>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="carUsageKm">Number of kilometers driven daily</label>
                  <Input
                    id="carUsageKm"
                    type="number"
                    value={userData.carUsageKm}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="vehicleType">Type of vehicle</label>
                  <Input
                    id="vehicleType"
                    type="text"
                    value={userData.vehicleType}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="fuelType">Fuel type</label>
                  <Input
                    id="fuelType"
                    type="text"
                    value={userData.fuelType}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
            </Row>
            {/* Add other fields for public transport and flights */}
          </Collapse>

          {/* Energy Consumption Section */}
          <h6 className="heading-small text-muted mb-4">
            Energy Consumption
            <Button
              color="link"
              onClick={() => toggleCollapse("energy")}
              size="sm"
              className="float-right"
            >
              {collapse.energy ? "Hide" : "Show"} Details
            </Button>
          </h6>
          <Collapse isOpen={collapse.energy}>
            <Row>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="electricityUsage">Monthly electricity consumption (kWh)</label>
                  <Input
                    id="electricityUsage"
                    type="number"
                    value={userData.electricityUsage}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="heatingMethod">Heating method</label>
                  <Input
                    id="heatingMethod"
                    type="text"
                    value={userData.heatingMethod}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
              <Col md="6">
                <FormGroup>
                  <label htmlFor="homeSize">Home size (sq ft)</label>
                  <Input
                    id="homeSize"
                    type="number"
                    value={userData.homeSize}
                    onChange={handleChange}
                  />
                </FormGroup>
              </Col>
            </Row>
          </Collapse>

          {/* Other Sections (Food, Waste, etc.) */}

          {/* Submit Button */}
          <div className="text-center mt-4">
            <Button color="primary" type="submit">
              Submit
            </Button>
          </div>
        </Form>
      </div>
    </>
  );
};

export default CarbonFootprintInput;
